import{_ as a,o as t,c as o,ao as r}from"./chunks/framework.Cg8nWxPv.js";const p=JSON.parse('{"title":"How-to guides","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/index.md","filePath":"how-to/index.md","lastUpdated":null}'),i={name:"how-to/index.md"};function h(l,e,n,s,d,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="How-to-guides" tabindex="-1">How-to guides <a class="header-anchor" href="#How-to-guides" aria-label="Permalink to &quot;How-to guides {#How-to-guides}&quot;">​</a></h1><p>Each guide solves one problem and assumes you can already start a server and push a window. If you cannot, read the <a href="./../tutorials/">tutorials</a> first. For the whole surface of a function, go to <a href="./../reference/">Reference</a>. For why the system is shaped this way, go to <a href="./../explanation/">Explanation</a>.</p><h2 id="Put-something-on-the-globe" tabindex="-1">Put something on the globe <a class="header-anchor" href="#Put-something-on-the-globe" aria-label="Permalink to &quot;Put something on the globe {#Put-something-on-the-globe}&quot;">​</a></h2><ul><li><p><a href="./primitives">Draw points, lines and areas</a> — the three families the <code>primitives</code> module draws, and the array shapes they take.</p></li><li><p><a href="./heatmap">Drape a scalar field over the globe</a> — a grid of values as colour on the surface.</p></li><li><p><a href="./models">Put your own model on a satellite</a> — a glTF file on an entity <code>primitives</code> owns, and what it costs to draw.</p></li><li><p><a href="./coordinates">Work in map coordinates</a> — degrees in, ECEF metres out, on the ellipsoid the session declared.</p></li></ul><h2 id="Answer-the-user" tabindex="-1">Answer the user <a class="header-anchor" href="#Answer-the-user" aria-label="Permalink to &quot;Answer the user {#Answer-the-user}&quot;">​</a></h2><ul><li><p><a href="./tooltips">Show a value on hover</a> — a hover listener that writes the tooltip for the entity under the cursor.</p></li><li><p><a href="./overlay-controls">Put controls in the overlay</a> — the caption, the colour bar, the checkbox, the dropdown, and the box that holds several.</p></li><li><p><a href="./floating">Put a box on screen</a> — a box anchored to the screen, to an entity, or to a point on the globe.</p></li></ul><h2 id="Decide-what-the-viewer-shows" tabindex="-1">Decide what the viewer shows <a class="header-anchor" href="#Decide-what-the-viewer-shows" aria-label="Permalink to &quot;Decide what the viewer shows {#Decide-what-the-viewer-shows}&quot;">​</a></h2><ul><li><p><a href="./furniture">Choose the on-screen furniture</a> — which of the Core&#39;s own items are on screen, and where the buttons sit.</p></li><li><p><a href="./static-scene">Show a scene with no clock</a> — one keyframe, and no time controls beside it.</p></li><li><p><a href="./basemap">Choose what the globe is textured with</a> — a basemap from the web or from a directory of your own tiles, and how to put satellites around the Moon.</p></li><li><p><a href="./camera-tour">Give a recording a tour</a> — declare where the camera looks, and when it goes there.</p></li></ul><h2 id="Write-JavaScript" tabindex="-1">Write JavaScript <a class="header-anchor" href="#Write-JavaScript" aria-label="Permalink to &quot;Write JavaScript {#Write-JavaScript}&quot;">​</a></h2><ul><li><a href="./no-build-module">Write a module with no build step</a> — several files, a library from the web, or a module held as a Julia string.</li></ul><h2 id="Move-the-data" tabindex="-1">Move the data <a class="header-anchor" href="#Move-the-data" aria-label="Permalink to &quot;Move the data {#Move-the-data}&quot;">​</a></h2><ul><li><a href="./large-arrays">Send large arrays</a> — what the wire carries cheaply, and what it refuses.</li></ul><h2 id="Deliver-the-data" tabindex="-1">Deliver the data <a class="header-anchor" href="#Deliver-the-data" aria-label="Permalink to &quot;Deliver the data {#Deliver-the-data}&quot;">​</a></h2><ul><li><a href="./lazy-delivery">Deliver a long mission a piece at a time</a> — declare the whole range, send a chunk, and answer <code>core/need</code> with the rest.</li></ul><h2 id="Look-at-the-scene" tabindex="-1">Look at the scene <a class="header-anchor" href="#Look-at-the-scene" aria-label="Permalink to &quot;Look at the scene {#Look-at-the-scene}&quot;">​</a></h2><ul><li><p><a href="./vscode-tab">Show a scene in a VSCode tab</a> — a live scene in an editor panel, with no forwarded port.</p></li><li><p><a href="./slate-cell">Show a scene in a notebook cell</a> — a live scene in a KaimonSlate cell, on the socket the notebook page already holds.</p></li></ul><h2 id="Look-at-what-happened" tabindex="-1">Look at what happened <a class="header-anchor" href="#Look-at-what-happened" aria-label="Permalink to &quot;Look at what happened {#Look-at-what-happened}&quot;">​</a></h2><ul><li><p><a href="./record-replay">Record and replay a session</a> — write the frames to a file, and drive a viewer from that file later.</p></li><li><p><a href="./inspect-the-wire">Look at what the wire carried</a> — read a frame, its header and its region by hand.</p></li></ul>',18)])])}const w=a(i,[["render",h]]);export{p as __pageData,w as default};
